"use client"

import * as React from "react"
import { useChat } from "@ai-sdk/react"
import { DefaultChatTransport, type UIMessage } from "ai"
import { AlertCircleIcon, ArrowDownIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import { FableProvider, type FableHostAction } from "../provider"
import type { FableImagePolicy } from "../safety"
import { FableComposer } from "./fable-composer"
import { FableMessage, Thinking } from "./fable-message"

export interface FableChatController {
  send: (text: string) => void
  clear: () => void
}

export interface FableChatProps {
  /** Route that streams AI SDK UI messages. */
  api?: string
  /** Extra JSON sent with every request, e.g. a model id. */
  body?: Record<string, unknown> | (() => Record<string, unknown>)
  title?: React.ReactNode
  description?: React.ReactNode
  suggestions?: { label: string; prompt: string }[]
  placeholder?: string
  images?: FableImagePolicy
  actions?: Record<string, FableHostAction>
  composerFooter?: React.ReactNode
  /** Show skipped-block diagnostics. */
  debug?: boolean
  onMessagesChange?: (messages: UIMessage[]) => void
  /** Lets a parent send prompts or clear the thread. */
  controllerRef?: React.Ref<FableChatController>
  className?: string
}

const resolveBody = (body: FableChatProps["body"]) => (typeof body === "function" ? body() : (body ?? {}))

/** Keeps the thread pinned to the newest message unless the reader scrolls up. */
function useStickToBottom(dependency: unknown) {
  const ref = React.useRef<HTMLDivElement>(null)
  const pinned = React.useRef(true)
  const [away, setAway] = React.useState(false)

  React.useEffect(() => {
    const node = ref.current
    if (!node) return
    const onScroll = () => {
      const distance = node.scrollHeight - node.scrollTop - node.clientHeight
      pinned.current = distance < 80
      setAway(distance > 240)
    }
    node.addEventListener("scroll", onScroll, { passive: true })
    return () => node.removeEventListener("scroll", onScroll)
  }, [])

  React.useLayoutEffect(() => {
    const node = ref.current
    if (node && pinned.current) node.scrollTop = node.scrollHeight
  }, [dependency])

  const toBottom = React.useCallback(() => {
    pinned.current = true
    ref.current?.scrollTo({ top: ref.current.scrollHeight, behavior: "smooth" })
  }, [])
  const pin = React.useCallback(() => {
    pinned.current = true
  }, [])

  return [ref, away, toBottom, pin] as const
}

export function FableChat({
  api = "/api/fable-chat",
  body,
  title = "What can I help with?",
  description,
  suggestions = [],
  placeholder,
  images,
  actions,
  composerFooter,
  debug,
  onMessagesChange,
  controllerRef,
  className,
}: FableChatProps) {
  const bodyRef = React.useRef(body)
  React.useLayoutEffect(() => {
    bodyRef.current = body
  })
  const [transport] = React.useState(() => new DefaultChatTransport({ api }))
  const { messages, sendMessage, setMessages, status, stop, error, regenerate, clearError } = useChat({ transport, experimental_throttle: 50 })
  const busy = status === "submitted" || status === "streaming"
  const [scrollRef, away, toBottom, pin] = useStickToBottom(messages)

  React.useEffect(() => {
    onMessagesChange?.(messages)
  }, [messages, onMessagesChange])

  // Always calls the latest chat helpers, but keeps one identity so blocks don't re-render on every chunk.
  const latest = React.useRef({ sendMessage, clearError, stop, setMessages, pin })
  React.useLayoutEffect(() => {
    latest.current = { sendMessage, clearError, stop, setMessages, pin }
  })
  const send = React.useCallback((text: string) => {
    if (!text.trim()) return
    latest.current.pin()
    latest.current.clearError()
    void latest.current.sendMessage({ text }, { body: resolveBody(bodyRef.current) })
  }, [])

  React.useImperativeHandle(
    controllerRef,
    () => ({
      send,
      clear: () => {
        void latest.current.stop()
        latest.current.setMessages([])
        latest.current.clearError()
      },
    }),
    [send]
  )

  const last = messages[messages.length - 1]
  const waiting = status === "submitted" || (status === "streaming" && last?.role === "assistant" && last.parts.every((part) => part.type === "step-start"))

  return (
    <FableProvider onReply={send} actions={actions} images={images} readOnly={busy}>
      <div className={cn("relative flex min-h-0 flex-1 flex-col", className)}>
        <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto overscroll-contain">
          <div className="mx-auto flex w-full max-w-3xl flex-col gap-8 px-4 pt-8 pb-6 sm:px-6">
            {messages.length === 0 ? (
              <div className="flex min-h-[50vh] flex-col items-center justify-center gap-6 text-center">
                <div className="space-y-2">
                  <h1 className="font-heading text-2xl font-semibold tracking-tight text-balance sm:text-3xl">{title}</h1>
                  {description ? <p className="mx-auto max-w-md text-sm text-pretty text-muted-foreground">{description}</p> : null}
                </div>
                {suggestions.length ? (
                  <div className="grid w-full max-w-xl gap-2 sm:grid-cols-2">
                    {suggestions.map((suggestion) => (
                      <button
                        key={suggestion.label}
                        type="button"
                        onClick={() => send(suggestion.prompt)}
                        className="rounded-xl bg-card px-4 py-3 text-start text-sm ring-1 ring-foreground/[0.08] transition-[background-color,box-shadow,scale] outline-none hover:bg-muted/50 hover:ring-foreground/15 focus-visible:ring-2 focus-visible:ring-ring active:scale-[0.98]"
                      >
                        <span className="font-medium">{suggestion.label}</span>
                        <span className="mt-0.5 line-clamp-1 block text-xs text-muted-foreground">{suggestion.prompt}</span>
                      </button>
                    ))}
                  </div>
                ) : null}
              </div>
            ) : (
              messages.map((message, index) => (
                <FableMessage
                  key={message.id}
                  message={message}
                  debug={debug}
                  streaming={busy && index === messages.length - 1}
                  onRegenerate={!busy && index === messages.length - 1 ? () => void regenerate({ body: resolveBody(bodyRef.current) }) : undefined}
                />
              ))
            )}
            {waiting ? <Thinking /> : null}
            {error ? (
              <div role="alert" className="flex items-start gap-3 rounded-xl bg-destructive/[0.06] px-4 py-3 text-sm ring-1 ring-destructive/20">
                <AlertCircleIcon className="mt-0.5 size-4 shrink-0 text-destructive" aria-hidden />
                <div className="min-w-0 flex-1">
                  <p className="font-medium">The response failed.</p>
                  <p className="text-muted-foreground">Check the server logs or try again.</p>
                </div>
                <Button size="sm" variant="outline" onClick={() => void regenerate({ body: resolveBody(bodyRef.current) })}>
                  Try again
                </Button>
              </div>
            ) : null}
          </div>
        </div>

        <div className="relative mx-auto w-full max-w-3xl px-4 pb-4 sm:px-6">
          {away ? (
            <Button
              size="icon-sm"
              variant="outline"
              onClick={toBottom}
              aria-label="Scroll to latest"
              className="absolute -top-10 left-1/2 -translate-x-1/2 rounded-full bg-background shadow-sm"
            >
              <ArrowDownIcon />
            </Button>
          ) : null}
          <FableComposer onSend={send} onStop={stop} busy={busy} placeholder={placeholder} footer={composerFooter} autoFocus />
        </div>
      </div>
    </FableProvider>
  )
}

"use client"

import * as React from "react"
import { CheckIcon, CopyIcon, RefreshCwIcon, WrenchIcon } from "lucide-react"
import { getToolName, isToolUIPart, type UIMessage } from "ai"

import { cn } from "@/lib/utils"

import { MemoProse } from "../blocks/prose"
import { IconAction, SwapIcon, useCopy } from "../blocks/shared"
import { specToMarkdown } from "../to-markdown"
import { FableToolPart, isFableToolPart } from "../tool-part"

function messageMarkdown(message: UIMessage) {
  return message.parts
    .map((part) => {
      if (part.type === "text") return part.text
      if (isFableToolPart(part)) return specToMarkdown((part as { input?: unknown }).input)
      return ""
    })
    .filter(Boolean)
    .join("\n\n")
}

export function FableMessage({
  message,
  streaming,
  onRegenerate,
  debug,
}: {
  message: UIMessage
  /** True while this message is the one being streamed. */
  streaming?: boolean
  onRegenerate?: () => void
  debug?: boolean
}) {
  const { copied, copy } = useCopy()

  if (message.role === "user") {
    const text = message.parts.map((part) => (part.type === "text" ? part.text : "")).join("")
    return (
      <div className="flex justify-end ps-10 motion-safe:animate-in motion-safe:fade-in-0 motion-safe:duration-200">
        <div className="max-w-[85%] rounded-[1.25rem] rounded-ee-md bg-muted px-4 py-2.5 text-[0.9375rem] leading-relaxed whitespace-pre-wrap text-foreground [overflow-wrap:anywhere]">
          {text}
        </div>
      </div>
    )
  }

  const hasContent = message.parts.some((part) => (part.type === "text" && part.text.trim()) || isFableToolPart(part))

  return (
    <div className="group/message flex flex-col gap-5" data-role="assistant">
      {message.parts.map((part, index) => {
        if (part.type === "text") {
          if (!part.text.trim()) return null
          return <MemoProse key={index}>{part.text}</MemoProse>
        }
        if (isFableToolPart(part)) {
          return <FableToolPart key={part.toolCallId} part={part} active={Boolean(streaming)} debug={debug} />
        }
        if (isToolUIPart(part)) {
          const name = getToolName(part).replace(/[_-]+/g, " ")
          const state = (part as { state?: string }).state
          return (
            <p key={index} className="inline-flex w-fit items-center gap-1.5 rounded-full bg-muted/60 px-2.5 py-1 text-xs text-muted-foreground">
              <WrenchIcon className={cn("size-3", state?.startsWith("input") && "motion-safe:animate-pulse")} aria-hidden />
              {state?.startsWith("input") ? `Using ${name}…` : `Used ${name}`}
            </p>
          )
        }
        return null
      })}
      {!streaming && hasContent ? (
        <div className="-ms-1.5 -mt-3 flex gap-0.5 opacity-0 transition-opacity group-hover/message:opacity-100 group-focus-within/message:opacity-100 [@media(hover:none)]:opacity-100">
          <IconAction label={copied ? "Copied" : "Copy response"} onClick={() => void copy(messageMarkdown(message))}>
            <SwapIcon swapped={copied} from={CopyIcon} to={CheckIcon} />
          </IconAction>
          {onRegenerate ? (
            <IconAction label="Regenerate" onClick={onRegenerate}>
              <RefreshCwIcon className="size-4" />
            </IconAction>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

export function Thinking() {
  return (
    <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground">
      <span className="flex gap-1" aria-hidden>
        {[0, 1, 2].map((dot) => (
          <span
            key={dot}
            className="size-1.5 rounded-full bg-muted-foreground/60 motion-safe:animate-bounce"
            style={{ animationDelay: `${dot * 120}ms`, animationDuration: "900ms" }}
          />
        ))}
      </span>
      Thinking
    </p>
  )
}

"use client"

import * as React from "react"
import { ArrowUpIcon, SquareIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

export function FableComposer({
  onSend,
  onStop,
  busy,
  placeholder = "Ask anything",
  autoFocus,
  className,
  footer,
}: {
  onSend: (text: string) => void
  onStop?: () => void
  busy?: boolean
  placeholder?: string
  autoFocus?: boolean
  className?: string
  footer?: React.ReactNode
}) {
  const [value, setValue] = React.useState("")
  const ref = React.useRef<HTMLTextAreaElement>(null)
  const canSend = value.trim().length > 0 && !busy

  const send = () => {
    if (!canSend) return
    onSend(value.trim())
    setValue("")
    ref.current?.focus()
  }

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault()
        send()
      }}
      className={cn(
        "rounded-[1.5rem] bg-card p-2 ring-1 ring-foreground/10 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_8px_24px_-12px_rgb(0_0_0/0.12)] transition-shadow focus-within:ring-foreground/20 dark:shadow-none",
        className
      )}
    >
      <label htmlFor="fable-composer" className="sr-only">
        Message
      </label>
      <textarea
        id="fable-composer"
        ref={ref}
        value={value}
        rows={1}
        autoFocus={autoFocus}
        placeholder={placeholder}
        onChange={(event) => setValue(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
            event.preventDefault()
            send()
          }
        }}
        className="field-sizing-content block max-h-48 min-h-11 w-full resize-none bg-transparent px-3 py-2.5 text-[0.9375rem] leading-6 outline-none placeholder:text-muted-foreground"
      />
      <div className="flex items-center justify-between gap-2 ps-2">
        <div className="min-w-0 text-xs text-muted-foreground">{footer}</div>
        {busy && onStop ? (
          <Button type="button" size="icon" onClick={onStop} aria-label="Stop" className="rounded-full">
            <SquareIcon className="size-3 fill-current" />
          </Button>
        ) : (
          <Button
            type="submit"
            size="icon"
            disabled={!canSend}
            aria-label="Send"
            className="rounded-full transition-[scale,opacity] active:scale-[0.96]"
          >
            <ArrowUpIcon />
          </Button>
        )}
      </div>
    </form>
  )
}

import { FableChat } from "@/components/fable-ui/chat/fable-chat"

export default function FableChatPage() {
  return (
    <main className="flex h-dvh flex-col bg-background">
      <FableChat
        api="/api/fable-chat"
        title="What can I help with?"
        suggestions={[
          { label: "Compare options", prompt: "Compare the three most popular note-taking apps in a table" },
          { label: "Plan a trip", prompt: "Plan a relaxed weekend in Copenhagen" },
          { label: "Draft an email", prompt: "Draft an email asking my team for feedback on the new onboarding" },
          { label: "Ask me questions", prompt: "Help me plan a birthday dinner — ask me what you need to know" },
        ]}
        // Images load only from hosts you list; others wait for a click.
        // images={{ allowedHosts: ["images.example-cdn.com"] }}
        // Side effects the model may request by name. Nothing else can run.
        // actions={{ "email.send": { confirm: "Send this email?", run: async (payload) => { … } } }}
      />
    </main>
  )
}

import { openai } from "@ai-sdk/openai"
import { convertToModelMessages, hasToolCall, stepCountIs, streamText, validateUIMessages, type InferUITools, type UIDataTypes, type UIMessage } from "ai"

import { fableSystemPrompt } from "@/components/fable-ui/prompt"
import { FABLE_TOOL_NAME, fableTool } from "@/components/fable-ui/tool"

export const maxDuration = 60

// Swap for any AI SDK provider, e.g. `anthropic("claude-sonnet-5-5")` from @ai-sdk/anthropic.
const model = openai(process.env.FABLE_MODEL ?? "gpt-5.5")

const tools = { [FABLE_TOOL_NAME]: fableTool }
type ChatMessage = UIMessage<unknown, UIDataTypes, InferUITools<typeof tools>>

const system = [
  "You are a helpful assistant. Be concise and specific.",
  fableSystemPrompt({
    // Tell the model where images may come from, e.g. "use URLs returned by the search_products tool".
    // Without a source it will not use image blocks.
    // imageSource: "…",
  }),
].join("\n\n")

export async function POST(request: Request) {
  let messages: ChatMessage[]
  try {
    const body = await request.json()
    messages = await validateUIMessages<ChatMessage>({ messages: body.messages, tools })
  } catch {
    return new Response("Invalid request", { status: 400 })
  }

  const result = streamText({
    model,
    system,
    // Keep requests bounded; long histories cost tokens on every turn.
    messages: await convertToModelMessages(messages.slice(-40), { tools }),
    tools,
    // The UI is the answer: stop once it has been shown.
    stopWhen: [hasToolCall(FABLE_TOOL_NAME), stepCountIs(5)],
    abortSignal: request.signal,
  })

  return result.toUIMessageStreamResponse({
    onError: () => "Something went wrong. Please try again.",
  })
}
